#[doc = r"Estimate saturated and moisture-adjusted osmotic potential.

# Arguments

  * electrical_conductivity: Electrical conductivity of a saturated soil extract. (dS/m)
  * theta: Current volumetric water content. (m^3/m^3)
  * theta_s: Saturated volumetric water content. (m^3/m^3)

# Returns

A [`Saxton2006SalinityResult`].

# Models

  * h(theta): Matric-plus-osmotic tension adjustment

# Notes

Prediction target: Osmotic potential from saturated-extract electrical conductivity.
The moisture adjustment assumes dissolved salt quantity remains near constant as water content
falls.

# Warnings

Precipitation, bonding, ionic nutrition, and toxicity can modify actual salinity effects."]
#[cfg_attr(feature = "inline", inline)]
#[must_use]
pub fn calc_ptf_saxton2006_salinity(
    electrical_conductivity: f64,
    theta: f64,
    theta_s: f64,
) -> Saxton2006SalinityResult {
    let saturated_osmotic_potential = 36.0f64 * electrical_conductivity;
    let osmotic_potential = theta_s / theta * saturated_osmotic_potential;
    Saxton2006SalinityResult {
        saturated_osmotic_potential,
        osmotic_potential,
    }
}
